const statementPeriod = `-- name: StatementPeriod :one
SELECT s.billing_party_id, s.period_year, s.period_month FROM billing_statements s WHERE s.id = $1
`

type StatementPeriodRow struct {
	BillingPartyID uuid.UUID
	PeriodYear     int32
	PeriodMonth    int32
}

// The party and period of a statement, unlocked (the columns never change): a status change takes the period's
// exclusive advisory lock with them before it locks the row.
func (q *Queries) StatementPeriod(ctx context.Context, id uuid.UUID) (StatementPeriodRow, error) {
	row := q.db.QueryRow(ctx, statementPeriod, id)
	var i StatementPeriodRow
	err := row.Scan(&i.BillingPartyID, &i.PeriodYear, &i.PeriodMonth)
	return i, err
}

const statementTotals = `-- name: StatementTotals :one
SELECT count(*)::int AS line_count,
       count(*) FILTER (WHERE row_type = 'trip')::int AS trip_only_count,
       count(*) FILTER (WHERE row_type = 'standby')::int AS standby_count,
       count(*) FILTER (WHERE row_type = 'multidrop_stop')::int AS multi_drop_count,
       coalesce(sum(amount_thb), 0)::float8 AS total
FROM billing_statement_lines
WHERE statement_id = $1
`

type StatementTotalsRow struct {
	LineCount      int32
	TripOnlyCount  int32
	StandbyCount   int32
	MultiDropCount int32
	Total          float64
}

// Exact NUMERIC sums of a statement's lines (main spec §6.2: SQL statement totals are exact), returned as float8.
func (q *Queries) StatementTotals(ctx context.Context, statementID uuid.UUID) (StatementTotalsRow, error) {
	row := q.db.QueryRow(ctx, statementTotals, statementID)
	var i StatementTotalsRow
	err := row.Scan(
		&i.LineCount,
		&i.TripOnlyCount,
		&i.StandbyCount,
		&i.MultiDropCount,
		&i.Total,
	)
	return i, err
}

const updateStatementTotals = `-- name: UpdateStatementTotals :exec
UPDATE billing_statements s
SET total_amount = a.total, trip_count = a.n, trip_only_count = a.n_trip, trip_subtotal = a.trip_sum,
    standby_count = a.n_standby, standby_subtotal = a.standby_sum, multi_drop_count = a.n_multi,
    multi_drop_subtotal = a.multi_sum, withholding_tax = ($1::text)::numeric(14,2),
    net_amount = a.total - ($1::text)::numeric(14,2)
FROM (SELECT count(*)::int AS n,
             count(*) FILTER (WHERE row_type = 'trip')::int AS n_trip,
             count(*) FILTER (WHERE row_type = 'standby')::int AS n_standby,
             count(*) FILTER (WHERE row_type = 'multidrop_stop')::int AS n_multi,
             coalesce(sum(amount_thb), 0) AS total,
             coalesce(sum(amount_thb) FILTER (WHERE row_type = 'trip'), 0) AS trip_sum,
             coalesce(sum(amount_thb) FILTER (WHERE row_type = 'standby'), 0) AS standby_sum,
             coalesce(sum(amount_thb) FILTER (WHERE row_type = 'multidrop_stop'), 0) AS multi_sum
      FROM billing_statement_lines WHERE statement_id = $2) a
WHERE s.id = $2
`

type UpdateStatementTotalsParams struct {
	WithholdingTax string
	ID             uuid.UUID
}

// Counts and subtotals from the lines, the withholding computed in Go (WithholdingTHB of the total and the stored
// rate), net = total - withholding as NUMERIC.
func (q *Queries) UpdateStatementTotals(ctx context.Context, arg UpdateStatementTotalsParams) error {
	_, err := q.db.Exec(ctx, updateStatementTotals, arg.WithholdingTax, arg.ID)
	return err
}
